import { Integration, Model, Plugin, Provider } from "@opencode/plugin";
import { resolve as resolvePath } from "node:path";
import { DIRECTORY_HEADER, EFFORT_HEADER, FORK_HEADER, LOCAL_API_KEY, MODEL_HEADER, PROVIDER_ID, PROVIDER_NAME, REQUEST_KIND_HEADER, SESSION_HEADER, } from "./constants.js";
import { refreshModelMetadata, researchedMetadataFor } from "./model-metadata.js";
import { fallbackAcpModelCatalog } from "./models.js";
import { getRuntime, onModelCatalogChange, startRuntime, stopRuntime } from "./runtime.js";
import { WorkspaceRegistry } from "./workspace-registry.js";
import { closeHostBridges } from "./host-tools.js";
import { sessionStore } from "./session-store.js";
import { sessionPool } from "./session-pool.js";
import { BoundedRetryQueue } from "./bounded-retry-queue.js";
import { ContextTelemetry } from "./telemetry-rpc.js";
import { onContextSnapshot, readContextSnapshot, markContextStale } from "./telemetry.js";
import { AgyError, retryAfterSeconds } from "./errors.js";
import { warn, info as lifecycleInfo } from "./log.js";
import { AGENT_OPTION, AntigravityLanguageModel, INSTRUCTIONS_OPTION } from "./language-model.js";
export const PLUGIN_ID = "opencode-antigravity";
export const INTEGRATION_ID = PROVIDER_ID;
// OpenCode runs its built-in DynamicProviderPlugin before user
// plugins. For an `aisdk:*` provider it tries to load a `create*` export from
// the provider package before our `sdk` hook can supply the real SDK. Use a
// local shim with a `create*` export so that loader succeeds; the hook below
// then replaces it with the ACP-backed SDK.
export const PROVIDER_PACKAGE = `aisdk:${new URL("./sdk-shim.mjs", import.meta.url).href}`;
async function retainWorkspace(directory) {
    await startRuntime(resolvePath(directory));
}
async function releaseWorkspace(directory) {
    await stopRuntime(resolvePath(directory));
}
function providerModel(model) {
    const id = Model.ID.make(model.id);
    const base = Model.Info.default(Provider.ID.make(PROVIDER_ID), id);
    const metadata = researchedMetadataFor(model);
    return {
        ...base,
        modelID: id,
        name: metadata ? model.name : `${model.name} (limits estimated)`,
        ...(model.family ? { family: Model.Family.make(model.family) } : {}),
        capabilities: {
            tools: true,
            input: ["text", "image"],
            output: ["text"],
        },
        limit: {
            context: metadata?.context ?? 32_768,
            output: metadata?.output ?? 8_192,
        },
        variants: Object.keys(model.variants ?? {}).map((variant) => ({ id: Model.VariantID.make(variant) })),
    };
}
export function buildProviderModels(catalog) {
    return catalog.models.map(providerModel);
}
function requestKind(kind) {
    if (kind === "title")
        return "title";
    if (kind === "compaction")
        return "compaction";
    if (kind === "generate")
        return "generate";
    return "chat";
}
const warnedTemperature = new Set();
function stripAcpOwnedOptions(event) {
    // ACP's own effort variants control reasoning; its Anthropic adapter does
    // not support model temperature overrides.
    delete event.options.reasoningEffort;
    if (event.options.temperature !== undefined) {
        // Warn once per session. A process-wide flag hides the notice from every
        // session that starts after the first one.
        const key = event.sessionID ?? "";
        if (!warnedTemperature.has(key)) {
            if (warnedTemperature.size >= 1_000)
                warnedTemperature.clear();
            warnedTemperature.add(key);
            warn("Ignoring temperature: generation sampling is owned by ACP", { reason: "unsupported_temperature" });
        }
    }
    delete event.options.temperature;
}
/** OpenCode's date and environment are supplied by the ACP harness itself. */
const ACP_SUPPLIED_INSTRUCTIONS = new Set(["core/date", "core/environment"]);
/** Extract OpenCode's instruction sources (AGENTS.md, skills, MCP guidance,
 * references) from the assembled system parts. The first part is OpenCode's
 * own prompt, which the agent role replaces. */
function instructionText(system) {
    if (!Array.isArray(system))
        return "";
    const texts = [];
    for (const part of system.slice(1)) {
        if (!part || typeof part !== "object")
            continue;
        const metadata = part.metadata;
        const sources = metadata?.experimental?.instructions;
        // Match OpenCode's own provider: a malformed source list falls back to the
        // rendered part text instead of silently dropping the instruction.
        if (Array.isArray(sources) && sources.every((source) => source && typeof source === "object" &&
            typeof source.key === "string" &&
            typeof source.text === "string")) {
            for (const source of sources) {
                if (ACP_SUPPLIED_INSTRUCTIONS.has(source.key))
                    continue;
                if (source.text.trim())
                    texts.push(source.text);
            }
            continue;
        }
        if (typeof part.text === "string" && part.text.trim())
            texts.push(part.text);
    }
    return texts.join("\n\n");
}
/** V2 plugin entrypoint. ACP owns Google auth; OpenCode sees only a local marker. */
export const AntigravityPlugin = Plugin.define({
    id: PLUGIN_ID,
    async setup(ctx) {
        const workspaces = new WorkspaceRegistry(retainWorkspace, releaseWorkspace);
        let unsubscribe;
        let disposed = false;
        let metadataTimer;
        const events = new AbortController();
        let stopTelemetry;
        let disposeTelemetry;
        const deletionQueue = new BoundedRetryQueue(async (sessionID) => {
            await sessionStore.markHostDeleted(sessionID);
            await closeHostBridges(sessionID);
            await sessionPool.quiesceHostSession(sessionID);
            await sessionStore.removeHostSession(sessionID);
        }, {
            concurrency: 4,
            retryDelayMs: 15_000,
            onError: () => warn("Deleted session cleanup waiting for ownership release", { reason: "deletion_cleanup_pending" }),
        });
        try {
            for (const sessionID of await sessionStore.deletedHosts())
                deletionQueue.enqueue(sessionID);
            await workspaces.add(ctx.location.directory);
            if (ctx.rpc) {
                const registration = await ctx.rpc.register(ContextTelemetry, {
                    read: async (input, context) => {
                        const { sessionID } = input;
                        const session = await ctx.session.get({ sessionID: sessionID });
                        if (resolvePath(session.location.directory) !== resolvePath(ctx.location.directory))
                            return context.error("wrong_location", "Context telemetry belongs to another location", { sessionID });
                        return readContextSnapshot(sessionID);
                    },
                });
                disposeTelemetry = registration.dispose;
                stopTelemetry = onContextSnapshot(snapshot => {
                    void ctx.session.get({ sessionID: snapshot.hostSessionID }).then(session => {
                        if (resolvePath(session.location.directory) === resolvePath(ctx.location.directory))
                            return registration.events.emit("changed", snapshot);
                    }).catch(() => undefined);
                });
            }
            const providerID = Provider.ID.make(PROVIDER_ID);
            const info = {
                ...Provider.Info.empty(providerID),
                name: PROVIDER_NAME,
                activation: "enabled",
                integrationID: Integration.ID.make(INTEGRATION_ID),
                package: PROVIDER_PACKAGE,
                settings: {
                    provider: PROVIDER_ID,
                    apiKey: LOCAL_API_KEY,
                },
            };
            await ctx.integration.transform((editor) => {
                editor.update(INTEGRATION_ID, (integration) => {
                    integration.name = PROVIDER_NAME;
                });
                // This is a local adapter, not a Google API-key provider. Keep the
                // integration ID equal to the provider ID for clients such as OpenChamber.
                editor.method.update({ integrationID: INTEGRATION_ID, method: { type: "key", label: "Local Antigravity" } });
            });
            // Match V1: install the non-secret loopback marker automatically. Google
            // authentication comes from the already-authenticated agy CLI.
            const connection = await ctx.integration.connection.active(INTEGRATION_ID);
            const credential = connection ? await ctx.integration.connection.resolve(connection) : undefined;
            if (credential?.type !== "key" || credential.key !== LOCAL_API_KEY) {
                await ctx.integration.connect.key({ integrationID: INTEGRATION_ID, key: LOCAL_API_KEY });
            }
            await ctx.provider.transform((editor) => {
                editor.add({ info, models: buildProviderModels(getRuntime()?.catalog ?? fallbackAcpModelCatalog()) });
            });
            unsubscribe = onModelCatalogChange(() => { void ctx.provider.reload().catch(() => undefined); });
            const refreshMetadata = () => { void refreshModelMetadata().then(() => { if (!disposed)
                return ctx.provider.reload(); }).catch(() => undefined); };
            refreshMetadata();
            metadataTimer = setInterval(refreshMetadata, 24 * 60 * 60_000);
            metadataTimer.unref?.();
            void (async () => {
                let attempts = 0;
                const lostBindings = new Map();
                while (!events.signal.aborted) {
                    try {
                        if (attempts) {
                            for (const [sessionID, expectedBindings] of lostBindings) {
                                if (await sessionStore.isHostDeleted(sessionID)) {
                                    await sessionStore.removeHostSession(sessionID);
                                    continue;
                                }
                                await sessionStore.reconcileLostBinding(sessionID, expectedBindings, async () => {
                                    await closeHostBridges(sessionID);
                                    await sessionPool.quiesceHostSession(sessionID);
                                    await sessionStore.invalidateHostSession(sessionID);
                                });
                            }
                            lostBindings.clear();
                            lifecycleInfo("Host lifecycle subscription reconnecting", { reason: "event_reconcile", attempt: attempts });
                        }
                        for await (const event of ctx.event.subscribe({ signal: events.signal })) {
                            attempts = 0;
                            const e = event;
                            if (e.type === "session.deleted" && e.data?.sessionID) {
                                await deletionQueue.enqueue(e.data.sessionID);
                                continue;
                            }
                            if (e.data?.sessionID && await sessionStore.isHostDeleted(e.data.sessionID))
                                continue;
                            if ((e.type === "session.execution.interrupted" || e.type === "session.execution.failed") && e.data?.sessionID)
                                await closeHostBridges(e.data.sessionID);
                        }
                    }
                    catch { /* Intentional cleanup exits below; unexpected loss retries. */ }
                    if (events.signal.aborted)
                        break;
                    try {
                        lostBindings.clear();
                        for (const [key, record] of await sessionStore.entries())
                            if (record.conversation?.hostSessionID) {
                                const sessionID = record.conversation.hostSessionID;
                                const bindings = lostBindings.get(sessionID) ?? [];
                                bindings.push([key, record.revision]);
                                lostBindings.set(sessionID, bindings);
                            }
                        for (const sessionID of lostBindings.keys()) {
                            try {
                                await markContextStale(sessionID);
                            }
                            catch {
                                warn("Could not mark disconnected context stale", { sessionID, reason: "event_stale_failed" });
                            }
                        }
                    }
                    catch {
                        warn("Could not reconcile disconnected session metadata", { reason: "event_metadata_failed" });
                    }
                    attempts++;
                    const delay = Math.min(30_000, 250 * 2 ** Math.min(attempts - 1, 7)) * (0.8 + Math.random() * 0.4);
                    warn("Host lifecycle subscription lost", { reason: "event_disconnect", attempt: attempts });
                    await new Promise(resolve => {
                        const finish = () => { clearTimeout(timer); events.signal.removeEventListener("abort", finish); resolve(); };
                        const timer = setTimeout(finish, delay);
                        timer.unref?.();
                        events.signal.addEventListener("abort", finish, { once: true });
                        if (events.signal.aborted)
                            finish();
                    });
                }
            })();
            // The agent system travels in provider options; the adapter reads it from
            // the same key the session hook wrote under. OpenCode's assembled system
            // is not forwarded to ACP for primary requests.
            for (const kind of ["context", "compaction", "generate"]) {
                await ctx.session.hook(kind, async (event) => {
                    stripAcpOwnedOptions(event);
                    const agent = await ctx.agent.get({ agentID: event.agent });
                    event.options[AGENT_OPTION] = agent.data.system ?? "";
                    event.options[INSTRUCTIONS_OPTION] = instructionText(event.system);
                }, { providerID: PROVIDER_ID });
            }
            await ctx.session.hook("title", stripAcpOwnedOptions, { providerID: PROVIDER_ID });
            await ctx.session.hook("retry", event => {
                if (!event.decision.retry)
                    return;
                // Older adapter instances reported a permanently closed pool as 502.
                // Repeating that request cannot revive its runtime; never loop on it.
                if (event.error.message.includes("The Antigravity session pool has been shut down")) {
                    event.decision = { retry: false };
                    return;
                }
                // AI SDK errors carry the provider's normalized hint directly; the
                // response body is still parsed for older shapes.
